@bp.delete("/invoices/<invoice_id>")
def delete_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return errors.problem(404, "Invoice not found")
    # Finalized invoices fall under the 10-year retention rule; only drafts can be deleted.
    if invoice.ledger_ref:
        return errors.problem(409, "Invoice is finalized", "Finalized invoices are retained and cannot be deleted.")
    del _INVOICES[invoice_id]
    return "", 204
